\label{lem:seminorm_norm}
Let Assumption~\ref{ass:moments} hold. Then the map $\|\cdot\|_{L^p_\mu(X^i,Y)}$ defined in \eqref{norm:Lp_operators} is a seminorm on $\mathcal L^i(X;Y)$, and it is weaker than $\|\cdot\|_{\mathcal L^i(X,Y)}$, since
\begin{equation}\label{eq:normr_bounded_opnorm}
    \|L\|_{L^p_\mu(X^i,Y)}\leq \|L\|_{\mathcal L^i(X,Y)}\left(\int_{X^i} \prod_{t=1}^i |h_t|_X^pd\mu(h_1,\ldots,h_i)\right)^{1/p}.
\end{equation}
Moreover, if {$\operatorname{supp}\mu\supset {(S^{X,1})^i}$, then it is a norm on $\mathcal L^i(X;Y)$; in particular, no quotient with respect to equivalence relations is needed, unlike for standard $L_\mu^p$-spaces.}

\label{rem:target_nondegeneracy}
We will use the following observation: if $\|\cdot\|_{L^p_\mu(X^i,Y)}$ is a norm on $\mathcal L^i(X,Y)$, then $\|\cdot\|_{L^p_\mu(X^i,\mathbb R)}$ is a norm on $\mathcal L^i(X,\mathbb R)$. Indeed, assume that $\|z\|_{L^p_\mu(X^i,\mathbb R)}=0$ and
fix $y_0\in Y\setminus\{0\}$. For every $z\in\mathcal L^i(X,\mathbb R)$, we have $$\|z\,y_0\|_{L^p_\mu(X^i,Y)}=|y_0|_Y\|z\|_{L^p_\mu(X^i,\mathbb R)}=0,$$ so that   $z\,y_0=0$, and hence $z=0$.

\label{prop:Lp_norm_separable}
$X$ is separable if and only if there exists a 
measure $\mu$ satisfying Assumption~\ref{ass:moments} such    that $\|\cdot\|_{L^p_{\mu}(X^i,Y)}$ is a norm on $\mathcal L^i(X,Y)$. Consequently, if $X$ is nonseparable, then $\|\cdot\|_{L^p_{\mu}(X^i,Y)}$ is a proper seminorm for every measure $\mu$ satisfying Assumption~\ref{ass:moments}.

\label{prop:finite-dim}
Let Assumption~\ref{ass:moments} hold. Assume that $\|\cdot\|_{L^p_\mu(X^i,Y)}$ is a norm on $\mathcal L^i(X,Y)$. Then:
\begin{enumerate}[(i)]
\item $\|\cdot\|_{L^p_\mu(X^i,Y)}$ and $\|\cdot\|_{\mathcal L^i(X,Y)}$ are equivalent if and only if $X$ is finite dimensional; if $X$ is infinite dimensional, then $\|\cdot\|_{L^p_\mu(X^i,Y)}$ induces a strictly weaker topology on $\mathcal L^i(X,Y)$ than $\|\cdot\|_{\mathcal L^i(X,Y)}$;
\item if $Y$ is a Banach space, then $\big(\mathcal L^i(X,Y),\|\cdot\|_{L^p_\mu(X^i,Y)}\big)$ is complete if and only if $X$ is finite dimensional.
\end{enumerate}

\label{thm:completion}
Let $i\geq1$, and consider one of the following settings:
\begin{enumerate}[(i)]
\item $X,Y,\nu$ are as in Example~\ref{ex:HS_norms_RKHS}, $\mu:=\otimes_{j=1}^i\nu$, $H:=X_\nu$, $\iota:=\iota_\nu$, and $\mathcal S:=\mathcal L_2^i(X_\nu,Y)$;
\item $X,Y,\gamma$ are as in Example~\ref{ex:gaussian_measures_radonifying}, $\mu:=\otimes_{j=1}^i\gamma$, $H:=X_\gamma$, $\iota:=\iota_\gamma$, and $\mathcal S:=\gamma^i(X_\gamma,Y)$.
\end{enumerate}
In both settings, Assumption~\ref{ass:moments} holds with $p=2$.
Let $\mathcal N:=\{L\in\mathcal L^i(X,Y):\|L\|_{L^2_\mu(X^i,Y)}=0\}$. Then:
\begin{enumerate}[label=(\alph*)]
\item the map $L\mapsto L\circ(\iota,\ldots,\iota)$ induces an isometric isomorphism from the completion of $\big(\mathcal L^i(X,Y)/\mathcal N,\|\cdot\|_{L^2_\mu(X^i,Y)}\big)$ onto $\mathcal S$;
\item if $Y\neq\{0\}$, then $\mathcal N=\{0\}$ if and only if $\iota(H)$ is dense in $X$.
\end{enumerate}

\label{lemma:multilinear}
    Let $T: X^i \rightarrow Y$ be multilinear, then the following are equivalent (i) $T$ is continuous; (ii) $T$ is continuous at one point; (iii) $\|T\|_{\mathcal L^i(X,Y)}=\sup \left\{\left|T\left(h_1, \ldots, h_i\right)\right |_Y:\left|h_1\right|_X = 1, \ldots,\left|h_i\right|_X = 1\right\}<\infty$; (iv) $\mathcal C=\left\{C \geq 0:\left|T\left(h_1, \ldots, h_i\right)\right|_Y \leq C \ \Pi_{j=1}^i|h_j|_X, \  \forall h_1, \ldots, h_i \in X \right\} \neq \varnothing$.
If one (hence, all) of these conditions {holds}, then $\|T\|_{\mathcal L^i(X,Y)} \in \mathcal C$ and $\|T\|_{\mathcal L^i(X,Y)}=\inf \mathcal C$.
